mapper.select:
SELECT board_skin_id, title, writer,content,hit,elike,reip,bdate,textemotion,role, row_num FROM (
SELECT board_skin_id, title, NICKNAME as writer,content,hit,elike,reip,bdate,textemotion,role,ROW_NUMBER()
OVER(ORDER BY board_skin_id desc) AS row_num FROM board_skin


                AND member_num = #{num}




                        AND NICKNAME LIKE '%' || #{searchValue} || '%'


                        AND title LIKE '%' || #{searchValue} || '%'


                        AND content LIKE '%' || #{searchValue} || '%'




) numbered_rows WHERE row_num BETWEEN #{begin} AND #{end}
